const app=document.querySelector('#app'),dialog=document.querySelector('#crop-dialog'),fileInput=document.querySelector('#file-input');
const initial={name:'Your name',bio:'Books, films, and everything in between.\nA few of my favorite things.',avatar:'assets/avatar.png',columns:2,collections:[{id:'books',title:'Books',slots:Array(9).fill(null)},{id:'films',title:'Films',slots:Array(9).fill(null)}]};
const ratios={square:1,portrait:788/1196,landscape:1090/570};
let state,db,draft,profileDraft,dirty=false,crop,uploadTarget,drag,descriptionIndex=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ratio=c=>ratios[c?.shape]||1;
function safeLink(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function notify(message){const n=document.querySelector('#notice');n.textContent=message;n.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.style.display='none',3500)}
async function init(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('three-by-three',1);r.onupgradeneeded=()=>r.result.createObjectStore('profile');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});state=await new Promise((resolve,reject)=>{const r=db.transaction('profile').objectStore('profile').get('main');r.onsuccess=()=>resolve(r.result||structuredClone(initial));r.onerror=()=>reject(r.error)});render()}catch{state=structuredClone(initial);render();notify('Browser storage unavailable. Changes cannot be saved.')}}
async function persist(next){if(!db)throw Error('Storage unavailable');await new Promise((resolve,reject)=>{const tx=db.transaction('profile','readwrite');tx.objectStore('profile').put(next,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});state=next}
// CSS crops the original source, so GIFs continue to animate in every view.
function imageMarkup(slot,r=1){if(!slot?.source&&!slot?.preview)return '';const src=slot.width&&slot.height?slot.source:(slot.preview||slot.source);let style='';if(slot.width&&slot.height){const relative=slot.width/slot.height;const z=slot.zoom||1;const width=100*Math.max(1,relative/r)*z,height=100*Math.max(1,r/relative)*z;style=`width:${width}%;height:${height}%;left:${50+(slot.x||0)*100}%;top:${50+(slot.y||0)*100}%;`;}return `<img src="${esc(src)}" alt="${esc(slot.alt||'Collection image')}" style="${style}" draggable="false">`}
function tiles(collection,mode='home'){return collection.slots.map((slot,i)=>{const hasImage=!!(slot?.source||slot?.preview),image=hasImage?imageMarkup(slot,ratio(collection)):`<span class="slot-number">${String(i+1).padStart(2,'0')}</span>`;if(mode==='editor')return `<div class="tile editor-tile ${hasImage?'':'empty'}" data-reorder="image"><button type="button" class="reorder-handle" aria-label="Move image ${i+1}" title="Drag to move. Use arrow keys to reorder.">move</button><div class="image-window">${image}</div><div class="tile-actions"><button type="button" data-image="${i}">edit image</button><button type="button" data-description="${i}">edit description</button></div></div>`;
if(mode==='profile')return `<div class="tile"><div class="image-window">${image}</div></div>`;
const href=safeLink(slot?.link);const tipId=`info-${collection.id}-${i}`;return `<div class="tile home-tile ${i%3===0?'tip-left':'tip-right'}"><${href?'a':'div'} class="image-window" ${href?`href="${esc(href)}"`:hasImage?'tabindex="0"':''} ${hasImage?`aria-describedby="${esc(tipId)}"`:''}>${image}</${href?'a':'div'}>${hasImage?`<aside class="speechbox info-box" id="${esc(tipId)}" role="tooltip"><h3>Info</h3><div>${esc(slot.info||'No description yet.')}</div></aside>`:''}</div>`}).join('')}
function downloadIcon(){return '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/></svg>'}
function gridClass(c){return `grid ${c.borders===false?'borderless':''}`}
function gridMarkup(c,mode){return `<div class="${gridClass(c)}" style="--ratio:${ratio(c)}">${tiles(c,mode)}</div>`}
function render(){const route=location.hash||'#/';const editing=route==='#/edit';document.querySelector('#home-link').setAttribute('aria-current',route==='#/'?'page':'false');document.querySelector('#edit-link').setAttribute('aria-current',route!=='#/'?'page':'false');if(route.startsWith('#/collection/'))return renderEditor(decodeURIComponent(route.slice(13)));draft=null;dirty=false;profileDraft=structuredClone(state);document.title=`${state.name} — 3×3`;app.innerHTML=`${editing?'':`<button type="button" class="download-button profile-download" data-download-profile aria-label="Download profile as PNG" title="Download profile as PNG">${downloadIcon()}</button>`}<section class="profile" aria-label="Profile">${editing?`<button class="avatar-button" aria-label="Change profile picture"><img class="avatar" src="${esc(state.avatar)}" alt="Profile picture"></button><input class="name-input" aria-label="Username" maxlength="60" value="${esc(state.name)}"><textarea class="bio-input" aria-label="Biography" maxlength="600">${esc(state.bio)}</textarea><button class="profile-save">Save profile</button>`:`<div class="profile-photo"><img class="avatar" src="${esc(state.avatar)}" alt="Profile picture"></div><h1>${esc(state.name)}</h1><p class="bio">${esc(state.bio)}</p>`}</section><div class="collection-bar"><span>Collections / ${String(state.collections.length).padStart(2,'0')}${editing?' · Drag to reorder; Save profile to keep changes.':''}</span><label>Per row <select id="columns" aria-label="Collections per row">${[2,3,4].map(n=>`<option value="${n}" ${n===(state.columns||2)?'selected':''}>${n}</option>`).join('')}</select></label></div><section class="collections" style="--columns:${state.columns||2}" aria-label="3 by 3 collections">${state.collections.map((c,i)=>`<article ${editing?'data-reorder="collection"':''} class="collection ${editing?'editable':''}">${editing?`<button type="button" class="reorder-handle" aria-label="Move ${esc(c.title)}" title="Drag to move. Use arrow keys to reorder.">move</button><a href="#/collection/${encodeURIComponent(c.id)}">`:''}<div class="card-frame">${gridMarkup(c,editing?'profile':'home')}</div><div class="collection-caption"><h2>${esc(c.title)}</h2>${editing?'':`<button type="button" class="download-button grid-download" data-download-grid="${esc(c.id)}" aria-label="Download ${esc(c.title)} as PNG" title="Download grid as PNG">${downloadIcon()}</button>`}<span>${String(i+1).padStart(2,'0')} / 3×3</span></div>${editing?'</a>':''}</article>`).join('')}${editing?'<a class="add-grid" href="#/collection/new" aria-label="Add a new 3 by 3"><b>+</b><span>Add a 3×3</span></a>':''}</section>`;
document.querySelector('#columns').onchange=async e=>{const columns=+e.target.value;document.querySelector('.collections').style.setProperty('--columns',columns);try{await persist({...state,columns})}catch{notify('Could not save layout.')}};if(editing){document.querySelector('.avatar-button').onclick=()=>pickImage('avatar');document.querySelector('.name-input').oninput=e=>{profileDraft.name=e.target.value;dirty=true};document.querySelector('.bio-input').oninput=e=>{profileDraft.bio=e.target.value;dirty=true};document.querySelector('.profile-save').onclick=saveProfile}}
async function saveProfile(){if(!profileDraft.name.trim())return notify('Enter a username.');try{await persist({...state,name:profileDraft.name.trim(),bio:profileDraft.bio,avatar:profileDraft.avatar,collections:profileDraft.collections});dirty=false;notify('Profile saved.')}catch{notify('Could not save. Your browser storage may be full.')}}
function renderEditor(id){const existing=state.collections.find(c=>c.id===id);if(id!=='new'&&!existing){location.hash='/edit';return}draft=structuredClone(existing||{id:crypto.randomUUID(),title:'',shape:'square',borders:true,slots:Array(9).fill(null)});dirty=false;app.innerHTML=`<section class="editor"><a class="back" href="#/edit">← Back to profile</a><h1>${existing?'Edit 3×3':'New 3×3'}</h1><input class="title-input" aria-label="3 by 3 title" maxlength="80" placeholder="Title of your 3×3" value="${esc(draft.title)}"><div class="grid-options"><label>Image shape <select id="shape"><option value="square">Square · 1:1</option><option value="portrait">Portrait · 788:1196</option><option value="landscape">Landscape · 1090:570</option></select></label><label><input type="checkbox" id="borders" ${draft.borders!==false?'checked':''}> Grid borders</label></div><div id="editable-grid">${gridMarkup(draft,'editor')}</div><p class="hint">Drag images to reorder. Use the move control with arrow keys, or hover to edit. Save 3×3 to keep changes.</p><div class="editor-actions"><button class="primary" id="save-grid">Save 3×3</button><a class="back" style="padding:12px" href="#/edit">Cancel</a></div><p class="save-error" role="alert"></p></section>`;document.querySelector('.title-input').oninput=e=>{draft.title=e.target.value;dirty=true};document.querySelector('#shape').value=draft.shape||'square';document.querySelector('#shape').onchange=e=>{draft.shape=e.target.value;dirty=true;refreshGrid()};document.querySelector('#borders').onchange=e=>{draft.borders=e.target.checked;dirty=true;refreshGrid()};bindSlots();document.querySelector('#save-grid').onclick=async()=>{if(!draft.title.trim()){document.querySelector('.save-error').textContent='Give your 3×3 a title.';document.querySelector('.title-input').focus();return}const next=structuredClone(state);draft.title=draft.title.trim();const index=next.collections.findIndex(c=>c.id===draft.id);if(index<0)next.collections.push(draft);else next.collections[index]=draft;try{await persist(next);dirty=false;location.hash='/';notify('3×3 saved.')}catch{document.querySelector('.save-error').textContent='Could not save. Browser storage may be full. Your edits are still here.'}}}
function refreshGrid(){document.querySelector('#editable-grid').innerHTML=gridMarkup(draft,'editor');bindSlots()}
function bindSlots(){document.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{const i=+b.dataset.image;uploadTarget=i;if(draft.slots[i]?.source)openCrop(draft.slots[i]);else pickImage(i)});document.querySelectorAll('[data-description]').forEach(b=>b.onclick=()=>openDescription(+b.dataset.description,b))}
function closeDescription(){document.querySelector('.description-box')?.remove();descriptionIndex=null}
function openDescription(i,button){closeDescription();descriptionIndex=i;const slot=draft.slots[i]||{};const panel=document.createElement('form');panel.className=`speechbox description-box ${i%3===0?'on-left':'on-right'}`;panel.setAttribute('aria-label',`Description for image ${i+1}`);panel.innerHTML=`<div class="description-head"><strong>Image ${i+1}</strong><button type="button" class="close-description" aria-label="Close description">×</button></div><label>INFO<textarea name="info" aria-label="Image information" maxlength="10000">${esc(slot.info||'')}</textarea></label><label>LINK<input name="link" aria-label="Image link" type="text" placeholder="https://" value="${esc(slot.link||'')}"></label><p class="description-error" role="alert"></p><button type="submit" class="primary">SAVE</button>`;button.closest('.tile').append(panel);panel.querySelector('.close-description').onclick=()=>{closeDescription();button.focus()};panel.onkeydown=e=>{if(e.key==='Escape'){e.stopPropagation();closeDescription();button.focus()}};panel.onsubmit=e=>{e.preventDefault();const info=panel.elements.info.value,link=panel.elements.link.value.trim();if(link&&!safeLink(link)){panel.querySelector('.description-error').textContent='Enter a full http:// or https:// link.';return}draft.slots[i]={...draft.slots[i],info,link};dirty=true;closeDescription();button.focus();notify('Description updated. Save 3×3 to keep your changes.')};panel.querySelector('textarea').focus()}
function pickImage(target){uploadTarget=target;fileInput.value='';fileInput.click()}
fileInput.onchange=async()=>{const file=fileInput.files[0];if(!file)return;if(!file.type.startsWith('image/'))return notify('Choose an image file.');if(file.size>30*1024*1024)return notify('Choose an image smaller than 30 MB.');try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const im=await loadImage(src);let source=src;const animated=file.type==='image/gif'||/\.gif$/i.test(file.name);if(!animated){const canvas=document.createElement('canvas'),scale=Math.min(1,1800/Math.max(im.width,im.height));canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);source=canvas.toDataURL('image/png')};openCrop({source,animated,zoom:1,x:0,y:0,alt:file.name.replace(/\.[^.]+$/,'')})}catch{notify('This image could not be opened. Try GIF, PNG, JPEG, or WebP.')}};
function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src})}
async function openCrop(slot){try{const im=await loadImage(slot.source);crop={...slot,zoom:slot.zoom||1,x:slot.x||0,y:slot.y||0,im,width:im.width,height:im.height};document.querySelector('#crop-image').src=slot.source;document.querySelector('#zoom').value=crop.zoom;document.querySelector('#crop-error').textContent='';document.querySelector('#crop-stage').style.aspectRatio=uploadTarget==='avatar'?1:ratio(draft);if(!dialog.open)dialog.showModal();paintCrop()}catch{notify('Image could not be loaded.')}}
function paintCrop(){const stage=document.querySelector('#crop-stage'),w=stage.clientWidth,h=stage.clientHeight;const scale=Math.max(w/crop.im.width,h/crop.im.height)*crop.zoom;const img=document.querySelector('#crop-image');img.style.width=crop.im.width*scale+'px';img.style.height=crop.im.height*scale+'px';img.style.left=(w-crop.im.width*scale)/2+crop.x*w+'px';img.style.top=(h-crop.im.height*scale)/2+crop.y*h+'px';document.querySelector('#zoom-value').value=Math.round(crop.zoom*100)+'%'}
document.querySelector('#zoom').oninput=e=>{crop.zoom=+e.target.value;paintCrop()};document.querySelector('#reset-crop').onclick=()=>{crop.zoom=1;crop.x=crop.y=0;document.querySelector('#zoom').value=1;paintCrop()};document.querySelector('#replace-image').onclick=()=>pickImage(uploadTarget);
const stage=document.querySelector('#crop-stage');stage.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,cx:crop.x,cy:crop.y};stage.setPointerCapture(e.pointerId)};stage.onpointermove=e=>{if(!drag)return;crop.x=drag.cx+(e.clientX-drag.x)/stage.clientWidth;crop.y=drag.cy+(e.clientY-drag.y)/stage.clientHeight;paintCrop()};stage.onpointerup=stage.onpointercancel=()=>drag=null;stage.onkeydown=e=>{const directions={ArrowLeft:[-.01,0],ArrowRight:[.01,0],ArrowUp:[0,-.01],ArrowDown:[0,.01]};if(directions[e.key]){e.preventDefault();crop.x+=directions[e.key][0];crop.y+=directions[e.key][1];paintCrop()}};window.addEventListener('resize',()=>{if(dialog.open&&crop)paintCrop()});
document.querySelector('#apply-crop').onclick=()=>{const {im,...saved}=crop;if(uploadTarget==='avatar'){if(saved.animated){profileDraft.avatar=saved.source}else{const c=document.createElement('canvas');c.width=c.height=600;const ctx=c.getContext('2d'),scale=Math.max(600/im.width,600/im.height)*crop.zoom;ctx.fillStyle='#080808';ctx.fillRect(0,0,600,600);ctx.drawImage(im,(600-im.width*scale)/2+crop.x*600,(600-im.height*scale)/2+crop.y*600,im.width*scale,im.height*scale);profileDraft.avatar=c.toDataURL('image/png')}document.querySelector('.avatar').src=profileDraft.avatar}else{const old=draft.slots[uploadTarget]||{};draft.slots[uploadTarget]={...saved,info:old.info||'',link:old.link||''};refreshGrid()}dirty=true;dialog.close()};
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#/"]');if(a&&dirty&&!confirm('Discard unsaved changes?'))e.preventDefault()});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});window.addEventListener('hashchange',()=>{closeDescription();render()});init();
function positionSpeechbox(box){const tile=box.closest('.tile');if(!tile)return;const rect=tile.getBoundingClientRect(),leftSide=tile.classList.contains('tip-left')||box.classList.contains('on-left');const narrow=innerWidth<=620;const desired=leftSide?rect.left-box.offsetWidth-12:rect.right+12;const x=Math.max(12,Math.min(narrow?rect.left:desired,innerWidth-box.offsetWidth-12));const y=Math.max(12,Math.min(narrow?rect.bottom+8:rect.top,innerHeight-box.offsetHeight-12));box.style.position='fixed';box.style.right='auto';box.style.left=x+'px';box.style.top=y+'px';box.classList.toggle('edge-clamped',narrow||Math.abs(x-desired)>1)}
document.addEventListener('pointerover',e=>{const tile=e.target.closest('.home-tile');if(tile){const box=tile.querySelector('.info-box');if(box)positionSpeechbox(box)}});
document.addEventListener('focusin',e=>{const box=e.target.closest('.description-box')||e.target.closest('.home-tile')?.querySelector('.info-box');if(box)positionSpeechbox(box)});
window.addEventListener('resize',()=>document.querySelectorAll('.speechbox').forEach(positionSpeechbox));
window.addEventListener('scroll',()=>document.querySelectorAll('.speechbox').forEach(positionSpeechbox),true);

// Move the complete entry, including the original image, crop, description and link.
function moveEntry(items,from,to){if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=items.length||to>=items.length||from===to)return false;items.splice(to,0,items.splice(from,1)[0]);return true}
function reorderItems(kind,from,to){if(kind==='image'){if(!draft||!moveEntry(draft.slots,from,to))return;closeDescription();dirty=true;refreshGrid();document.querySelectorAll('[data-reorder="image"] .reorder-handle')[to]?.focus();notify(`Image moved to position ${to+1}. Save 3×3 to keep changes.`)}else{if(!profileDraft||!moveEntry(profileDraft.collections,from,to))return;const cards=[...document.querySelectorAll('[data-reorder="collection"]')];const parent=cards[from].parentElement;parent.insertBefore(cards[from],from<to?cards[to].nextSibling:cards[to]);[...parent.querySelectorAll('[data-reorder="collection"]')].forEach((card,i)=>{card.querySelector('.collection-caption span').textContent=String(i+1).padStart(2,'0')+' / 3×3'});dirty=true;cards[from].querySelector('.reorder-handle').focus();notify(`Collection moved to position ${to+1}. Save profile to keep changes.`)}}
let reorderDrag=null,suppressReorderClick=false;
function reorderPeers(kind){return [...document.querySelectorAll(`[data-reorder="${kind}"]`)]}
function finishReorder(commit){const d=reorderDrag;if(!d)return;reorderDrag=null;document.body.classList.remove('reordering');document.querySelectorAll('.drag-source,.drop-target').forEach(el=>el.classList.remove('drag-source','drop-target'));if(app.hasPointerCapture?.(d.pointerId))app.releasePointerCapture(d.pointerId);if(d.active){suppressReorderClick=true;setTimeout(()=>suppressReorderClick=false,0);if(commit&&d.to!==null)reorderItems(d.kind,d.from,d.to)}}
app.addEventListener('pointerdown',e=>{if(e.button!==0||dialog.open)return;const item=e.target.closest('[data-reorder]');if(!item||e.target.closest('.description-box'))return;const handle=e.target.closest('.reorder-handle');if(!handle&&e.target.closest('button,input,textarea,select'))return;if(e.pointerType==='touch'&&!handle)return;const kind=item.dataset.reorder;if(kind==='image'&&!handle&&!draft.slots[reorderPeers(kind).indexOf(item)]?.source&&!draft.slots[reorderPeers(kind).indexOf(item)]?.preview)return;reorderDrag={kind,item,from:reorderPeers(kind).indexOf(item),to:null,x:e.clientX,y:e.clientY,pointerId:e.pointerId,active:false}});
app.addEventListener('pointermove',e=>{const d=reorderDrag;if(!d||d.pointerId!==e.pointerId)return;if(!d.active&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<6)return;if(!d.active){d.active=true;app.setPointerCapture(e.pointerId);d.item.classList.add('drag-source');document.body.classList.add('reordering')}e.preventDefault();document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));const target=document.elementFromPoint(e.clientX,e.clientY)?.closest(`[data-reorder="${d.kind}"]`);d.to=target?reorderPeers(d.kind).indexOf(target):null;if(target&&target!==d.item)target.classList.add('drop-target');if(e.clientY<60)window.scrollBy(0,-18);else if(e.clientY>innerHeight-60)window.scrollBy(0,18)});
window.addEventListener('pointerup',()=>finishReorder(true));window.addEventListener('pointercancel',()=>finishReorder(false));window.addEventListener('blur',()=>finishReorder(false));
app.addEventListener('dragstart',e=>{if(e.target.closest('[data-reorder]'))e.preventDefault()});
document.addEventListener('click',e=>{if(suppressReorderClick){e.preventDefault();e.stopImmediatePropagation()}},true);
app.addEventListener('keydown',e=>{if(e.key==='Escape'&&reorderDrag){e.preventDefault();finishReorder(false);return}const handle=e.target.closest('.reorder-handle');if(!handle)return;const item=handle.closest('[data-reorder]'),kind=item.dataset.reorder,peers=reorderPeers(kind),from=peers.indexOf(item);const columns=kind==='image'?3:getComputedStyle(item.parentElement).gridTemplateColumns.split(' ').length;const delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-columns,ArrowDown:columns}[e.key];if(delta!==undefined){e.preventDefault();const to=from+delta;if(to>=0&&to<peers.length)reorderItems(kind,from,to)}});
